// Validates and normalizes the intake payload from Fluent Forms (or any generic JSON
// form provider). Fails loudly with a descriptive error if a required field is missing --
// a silent failure here would generate documents with blank client-name fields.
const raw = $input.first().json.body || $input.first().json;

const required = ['full_name', 'email', 'matter_type'];
const missing = required.filter(f => !raw[f] || String(raw[f]).trim() === '');

const is_valid_intake = missing.length === 0;

return [{ json: {
  full_name:       String(raw.full_name || '').trim(),
  email:           String(raw.email || '').trim().toLowerCase(),
  phone:           String(raw.phone || '').trim(),
  practice_area:   String(raw.matter_type || '').trim(),
  case_details:    String(raw.case_details || '').trim(),
  referral_source: String(raw.referral_source || '').trim(),
  is_valid_intake,
  missing_fields:  missing,
  submitted_at:    new Date().toISOString(),
} }];

// Which documents to auto-fill for each practice area -- edit this map to match your
// firm's own template library. 'method' decides which engine fills the document: the
// retainer goes through DocuSign (it's the one that gets signed) as a draft envelope for
// the attorney to review and send manually; everything else goes through the Google Docs
// merge-and-export-PDF path. Each entry's template_var names the n8n Variable holding that
// template's ID -- a DocuSign template ID for method 'docusign', a Google Doc file ID for
// method 'google_docs'.
const TEMPLATE_MAP = {
  'Family Law': [
    { doc_label: 'Retainer Agreement', method: 'docusign', template_var: 'DOCUSIGN_RETAINER_TEMPLATE_ID' },
    { doc_label: 'Client Intake Form', method: 'google_docs', template_var: 'TEMPLATE_INTAKE_DOC_ID' },
  ],
  'Personal Injury': [
    { doc_label: 'Retainer Agreement', method: 'docusign', template_var: 'DOCUSIGN_RETAINER_TEMPLATE_ID' },
    { doc_label: 'Client Intake Form', method: 'google_docs', template_var: 'TEMPLATE_INTAKE_DOC_ID' },
    { doc_label: 'Court Cover Sheet', method: 'google_docs', template_var: 'TEMPLATE_COVER_SHEET_DOC_ID' },
  ],
  'Estate Planning': [
    { doc_label: 'Retainer Agreement', method: 'docusign', template_var: 'DOCUSIGN_RETAINER_TEMPLATE_ID' },
    { doc_label: 'Client Intake Form', method: 'google_docs', template_var: 'TEMPLATE_INTAKE_DOC_ID' },
  ],
  // Add a row per practice area your firm handles. Omit any document type a practice
  // area doesn't need -- e.g. most practice areas never need a court cover sheet.
};

const item = $input.first().json;
const configured = TEMPLATE_MAP[item.practice_area] || [];

const docs = configured
  .map(c => ({ doc_label: c.doc_label, method: c.method, template_doc_id: $vars[c.template_var] }))
  .filter(d => !!d.template_doc_id); // skip any template the firm hasn't configured a Variable for yet

return [{ json: {
  ...item,
  docs,
  doc_count: docs.length,
  has_docs: docs.length > 0,
} }];

// Fans out into one item per document to generate -- everything downstream through the
// export step processes one document at a time, then the Aggregate step recombines them.
const { docs, doc_count, has_docs, ...intake } = $input.first().json;
return docs.map(d => ({ json: { ...intake, ...d } }));

// Builds the envelope-creation request for the retainer's DocuSign template. Creates the
// envelope in 'created' (draft) status -- never 'sent' -- so the attorney reviews and sends
// it manually from inside DocuSign; this workflow never signs or sends anything on its own.
// Tab labels must match your DocuSign template's field labels exactly (case-sensitive) --
// add or remove entries here to match what your retainer template actually uses.
const doc = $('Split Into One Item Per Document').item.json;
const account = $input.first().json.accounts[0];

const templateRoles = [{
  email: doc.email,
  name: doc.full_name,
  roleName: $vars.DOCUSIGN_RETAINER_ROLE_NAME,
  tabs: {
    textTabs: [
      { tabLabel: 'full_name', value: doc.full_name },
      { tabLabel: 'email', value: doc.email },
      { tabLabel: 'phone', value: doc.phone || 'Not provided' },
      { tabLabel: 'practice_area', value: doc.practice_area },
      { tabLabel: 'case_details', value: doc.case_details || '' },
      { tabLabel: 'date', value: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) },
    ],
  },
}];

return [{ json: {
  ...doc,
  docusign_base_uri: account.base_uri,
  docusign_account_id: account.account_id,
  envelope_request: {
    templateId: doc.template_doc_id,
    status: 'created',
    templateRoles,
  },
} }];

// Normalizes this branch's result to the same shape 'Build Google Docs Result' produces,
// so 'Aggregate Filled Documents' can handle both engines uniformly. No binary here -- the
// draft lives inside DocuSign itself, there's no separate file to attach to the review email.
const doc = $('Split Into One Item Per Document').item.json;
const envelope = $input.first().json;

return [{
  json: {
    doc_label: doc.doc_label,
    method: 'docusign',
    full_name: doc.full_name,
    email: doc.email,
    practice_area: doc.practice_area,
    envelope_id: envelope.envelopeId,
  },
  binary: {},
}];

// Builds the batchUpdate requests that replace every {{merge_tag}} in the copied
// template with this intake's actual field values. Add a row here for every merge tag
// your firm's templates use -- the tag text must match exactly (case-sensitive) what's
// typed into the Google Doc.
const item = $('Split Into One Item Per Document').item.json; // intake fields + doc_label + template_doc_id
const newDocId = $input.first().json.id; // from Copy Template Document's response

const MERGE_FIELDS = {
  '{{full_name}}':        item.full_name,
  '{{email}}':             item.email,
  '{{phone}}':             item.phone || 'Not provided',
  '{{practice_area}}':     item.practice_area,
  '{{case_details}}':      item.case_details || '',
  '{{referral_source}}':   item.referral_source || 'Not provided',
  '{{date}}':              new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }),
};

const requests = Object.entries(MERGE_FIELDS).map(([tag, value]) => ({
  replaceAllText: {
    containsText: { text: tag, matchCase: true },
    replaceText: String(value),
  },
}));

return [{ json: { ...item, new_doc_id: newDocId, batch_requests: requests } }];

// Normalizes this branch's result to the same shape 'Build DocuSign Result' produces, so
// 'Aggregate Filled Documents' can handle both engines uniformly. Also re-attaches doc_label
// explicitly -- Export Filled Document As PDF's own response replaces the item's json with
// Drive's file metadata, dropping doc_label otherwise.
const doc = $('Split Into One Item Per Document').item.json;
const fileData = $input.first().binary && $input.first().binary.data;

return [{
  json: {
    doc_label: doc.doc_label,
    method: 'google_docs',
    full_name: doc.full_name,
    email: doc.email,
    practice_area: doc.practice_area,
  },
  binary: fileData ? { data: fileData } : {},
}];

// Combines every generated document into a single item for one review email: Google
// Docs results carry a PDF to attach; DocuSign results carry an envelope_id to reference
// instead (nothing to attach -- the draft lives inside DocuSign itself). Builds the full
// email/audit-log message text here rather than in downstream node expressions, since
// mixing two very different result shapes is easier to get right in real code.
const items = $input.all();

const binary = {};
const pdfLabels = [];
const docusignItems = [];
let fileIdx = 0;

for (const item of items) {
  if (item.json.method === 'docusign') {
    docusignItems.push({ label: item.json.doc_label, envelope_id: item.json.envelope_id });
    continue;
  }
  const fileData = item.binary && item.binary.data;
  if (!fileData) continue; // this document's export failed upstream -- skip it, don't break the others
  const key = `file${fileIdx++}`;
  binary[key] = { ...fileData, fileName: `${item.json.doc_label.replace(/[^a-zA-Z0-9 ._-]/g, '')}.pdf` };
  pdfLabels.push(item.json.doc_label);
}

const first = items[0].json;
const doc_count = pdfLabels.length + docusignItems.length;

const lines = [
  `New intake for ${first.full_name} (${first.practice_area}).`,
  '',
  `${doc_count} document(s) generated from the intake data:`,
];
pdfLabels.forEach(l => lines.push(`  • ${l} — PDF attached below for review`));
docusignItems.forEach(d => lines.push(`  • ${d.label} — draft envelope created in DocuSign (ID ${d.envelope_id}). Find it under Manage → Drafts to review and send.`));
lines.push('', 'These are field-fills only -- review every document before sending to the client, filing, or sending for signature. Nothing has been sent or signed automatically.');

const email_body = lines.join('\n');
const email_subject = `${doc_count} document(s) ready for review — ${first.full_name}`;
const audit_summary = `${doc_count} document(s) filled from intake: ${[...pdfLabels, ...docusignItems.map(d => d.label + ' (DocuSign draft)')].join(', ')}.`;

return [{
  json: {
    full_name:      first.full_name,
    email:          first.email,
    practice_area:  first.practice_area,
    pdf_labels:     pdfLabels,
    docusign_items: docusignItems,
    doc_count,
    email_body,
    email_subject,
    audit_summary,
  },
  binary,
}];
